-- ----------------------------------------------------------------------------
-- 0001_init.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- PromptWorkspace Cloud — initial schema (task graph)
-- Apply in the Supabase SQL editor or via `psql`. Table names are prefixed pw_.
--
-- Privacy note: model CREDENTIALS are never stored in the cloud. There is no
-- api_key / token column anywhere here by design.

create extension if not exists "pgcrypto";

-- Projects -------------------------------------------------------------------
create table if not exists pw_projects (
    id                uuid primary key default gen_random_uuid(),
    name              text not null,
    owner_id          text not null,
    onboarding_state  text not null default 'not_started',
    stage_state       jsonb not null default
                        '{"scope":"active","spec":"locked","skill":"locked"}'::jsonb,
    created_at        timestamptz not null default now(),
    updated_at        timestamptz not null default now()
);
create index if not exists idx_pw_projects_owner on pw_projects (owner_id);

-- Requirements (from Scope) --------------------------------------------------
create table if not exists pw_requirements (
    id           uuid primary key default gen_random_uuid(),
    project_id   uuid not null references pw_projects (id) on delete cascade,
    title        text not null,
    description  text not null default '',
    status       text not null default 'draft',
    updated_at   timestamptz not null default now()
);
create index if not exists idx_pw_requirements_project on pw_requirements (project_id);
create index if not exists idx_pw_requirements_updated on pw_requirements (project_id, updated_at);

-- Spec documents (from Spec / plan) ------------------------------------------
create table if not exists pw_spec_documents (
    id              uuid primary key default gen_random_uuid(),
    project_id      uuid not null references pw_projects (id) on delete cascade,
    requirement_id  uuid not null references pw_requirements (id) on delete cascade,
    content         text not null default '',
    version         integer not null default 1,
    status          text not null default 'draft',
    approved_by     text,
    updated_at      timestamptz not null default now()
);
create index if not exists idx_pw_specs_project on pw_spec_documents (project_id);
create index if not exists idx_pw_specs_updated on pw_spec_documents (project_id, updated_at);

-- Tasks ----------------------------------------------------------------------
create table if not exists pw_tasks (
    id                   uuid primary key default gen_random_uuid(),
    project_id           uuid not null references pw_projects (id) on delete cascade,
    spec_id              uuid references pw_spec_documents (id) on delete set null,
    title                text not null,
    status               text not null default 'todo',
    feature_tag          text,
    -- {text: string}[] to match the Ideva Kit card renderer. Do not flatten.
    acceptance_criteria  jsonb not null default '[]'::jsonb,
    updated_at           timestamptz not null default now()
);
create index if not exists idx_pw_tasks_project on pw_tasks (project_id);
create index if not exists idx_pw_tasks_updated on pw_tasks (project_id, updated_at);

-- Artifacts (generated code / PRs / docs) ------------------------------------
create table if not exists pw_artifacts (
    id           uuid primary key default gen_random_uuid(),
    project_id   uuid not null references pw_projects (id) on delete cascade,
    task_id      uuid not null references pw_tasks (id) on delete cascade,
    kind         text not null default 'code',
    uri          text not null,
    commit_sha   text,
    updated_at   timestamptz not null default now()
);
create index if not exists idx_pw_artifacts_project on pw_artifacts (project_id);
create index if not exists idx_pw_artifacts_updated on pw_artifacts (project_id, updated_at);

-- Agent runs (which model did what) ------------------------------------------
create table if not exists pw_agent_runs (
    id           uuid primary key default gen_random_uuid(),
    project_id   uuid not null references pw_projects (id) on delete cascade,
    task_id      uuid not null references pw_tasks (id) on delete cascade,
    model_role   text not null default 'code',
    action       text not null default '',
    status       text not null default 'running',
    evidence     jsonb not null default '{}'::jsonb,
    updated_at   timestamptz not null default now()
);
create index if not exists idx_pw_agent_runs_project on pw_agent_runs (project_id);
create index if not exists idx_pw_agent_runs_updated on pw_agent_runs (project_id, updated_at);

-- NOTE: Row Level Security is intentionally deferred to the auth milestone.
-- When Supabase Auth lands, enable RLS on every table and scope rows by
-- owner_id / project membership.

-- ----------------------------------------------------------------------------
-- 0002_soft_delete.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- PromptWorkspace Cloud — Milestone 1: tombstone soft-delete
-- Adds a nullable deleted_at column to every graph entity. A delete is just
-- an upsert that sets deleted_at (see docs/plans/0001-cloud-deletes-and-auth.md).
--
-- Semantics:
--   * Bootstrap pull (no `since`)  -> live rows only (deleted_at is null)
--   * Incremental pull (`since` set) -> everything changed, tombstones included
--
-- Additive and backward-compatible: old clients that never send deleted_at
-- keep working exactly as before.

alter table pw_requirements   add column if not exists deleted_at timestamptz;
alter table pw_spec_documents add column if not exists deleted_at timestamptz;
alter table pw_tasks          add column if not exists deleted_at timestamptz;
alter table pw_artifacts      add column if not exists deleted_at timestamptz;
alter table pw_agent_runs     add column if not exists deleted_at timestamptz;

-- Bootstrap pulls filter on (project_id, deleted_at is null); partial index
-- keeps that cheap without penalizing the incremental-pull index above.
create index if not exists idx_pw_requirements_live   on pw_requirements   (project_id) where deleted_at is null;
create index if not exists idx_pw_spec_documents_live on pw_spec_documents (project_id) where deleted_at is null;
create index if not exists idx_pw_tasks_live          on pw_tasks          (project_id) where deleted_at is null;
create index if not exists idx_pw_artifacts_live      on pw_artifacts      (project_id) where deleted_at is null;
create index if not exists idx_pw_agent_runs_live     on pw_agent_runs     (project_id) where deleted_at is null;

-- Tombstone GC: purge_expired_tombstones() runs on TOMBSTONE_TTL_DAYS from
-- app config; scoped to rows whose deleted_at is old enough that every
-- client has plausibly synced past them. Safe by construction — it only
-- ever removes rows that are already tombstoned (deleted_at not null).

-- ----------------------------------------------------------------------------
-- 0003_auth_workspaces.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- PromptWorkspace Cloud — Milestone 2: Supabase Auth, workspaces & RLS
--
-- Introduces the workspace access-control tier. Projects move from owner-only
-- to workspace-scoped; access is by membership. Per ADR 0010 §5 the cloud
-- stores only Git *metadata* (Option C) — never a raw credential.
--
-- Rollout (see docs/plans/0001-cloud-deletes-and-auth.md, M2):
--   1. Apply this migration (tables + projects.workspace_id nullable) + backfill.
--   2. Deploy backend with AUTH_MODE=stub, workspace_id optional — verify.
--   3. Enable RLS + flip AUTH_MODE=supabase + JWT-scoped client together.
--   4. Cleanup migration 0006: workspace_id NOT NULL, drop legacy owner_id.

-- Workspaces -----------------------------------------------------------------
create table if not exists pw_workspaces (
    id           uuid primary key default gen_random_uuid(),
    name         text not null,
    created_by   uuid not null,                       -- auth.users.id
    -- Non-secret Git metadata only: {repo_url, provider, default_branch}.
    git_config   jsonb not null default '{}'::jsonb,
    created_at   timestamptz not null default now(),
    updated_at   timestamptz not null default now()
);

-- Membership -----------------------------------------------------------------
create table if not exists pw_workspace_members (
    workspace_id  uuid not null references pw_workspaces (id) on delete cascade,
    user_id       uuid not null,                      -- auth.users.id
    role          text not null default 'member',     -- 'admin' | 'member'
    invited_by    uuid,
    created_at    timestamptz not null default now(),
    primary key (workspace_id, user_id)
);
create index if not exists idx_pw_members_user on pw_workspace_members (user_id);

-- Invitations ----------------------------------------------------------------
create table if not exists pw_invitations (
    id            uuid primary key default gen_random_uuid(),
    workspace_id  uuid not null references pw_workspaces (id) on delete cascade,
    email         text not null,
    role          text not null default 'member',
    token         text not null unique,
    status        text not null default 'pending',    -- pending|accepted|revoked|expired
    invited_by    uuid not null,
    expires_at    timestamptz not null,
    created_at    timestamptz not null default now()
);
create index if not exists idx_pw_invitations_ws on pw_invitations (workspace_id);

-- Projects gain a workspace --------------------------------------------------
alter table pw_projects add column if not exists workspace_id uuid references pw_workspaces (id) on delete cascade;
create index if not exists idx_pw_projects_workspace on pw_projects (workspace_id);

-- Backfill: give every legacy owner a personal workspace, make them its admin,
-- and move their projects into it. Idempotent-ish (guarded by workspace_id null).
do $$
declare
    legacy_owner text;
    new_ws uuid;
begin
    for legacy_owner in
        select distinct owner_id from pw_projects where workspace_id is null
    loop
        insert into pw_workspaces (name, created_by)
        values (legacy_owner || '''s workspace', legacy_owner::uuid)
        returning id into new_ws;

        insert into pw_workspace_members (workspace_id, user_id, role, invited_by)
        values (new_ws, legacy_owner::uuid, 'admin', legacy_owner::uuid)
        on conflict do nothing;

        update pw_projects set workspace_id = new_ws
        where owner_id = legacy_owner and workspace_id is null;
    end loop;
end $$;

-- Row Level Security ---------------------------------------------------------
-- The backend forwards the caller's JWT so Postgres enforces membership as
-- defense in depth beneath the app-layer checks. Enable at the M2 cutover.
alter table pw_workspaces        enable row level security;
alter table pw_workspace_members enable row level security;
alter table pw_projects          enable row level security;
alter table pw_requirements      enable row level security;
alter table pw_spec_documents    enable row level security;
alter table pw_tasks             enable row level security;
alter table pw_artifacts         enable row level security;
alter table pw_agent_runs        enable row level security;

create or replace function pw_is_member(ws uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from pw_workspace_members m
    where m.workspace_id = ws and m.user_id = auth.uid()
  );
$$;

create or replace function pw_is_admin(ws uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from pw_workspace_members m
    where m.workspace_id = ws and m.user_id = auth.uid() and m.role = 'admin'
  );
$$;

-- Workspace: readable by members, writable by admins.
drop policy if exists pw_ws_read on pw_workspaces;
create policy pw_ws_read  on pw_workspaces for select using (pw_is_member(id));
drop policy if exists pw_ws_write on pw_workspaces;
create policy pw_ws_write on pw_workspaces for all
  using (pw_is_admin(id)) with check (created_by = auth.uid() or pw_is_admin(id));

-- Membership rows: visible to members of the same workspace; admins manage.
drop policy if exists pw_members_read on pw_workspace_members;
create policy pw_members_read  on pw_workspace_members for select using (pw_is_member(workspace_id));
drop policy if exists pw_members_write on pw_workspace_members;
create policy pw_members_write on pw_workspace_members for all
  using (pw_is_admin(workspace_id)) with check (pw_is_admin(workspace_id));

-- Projects: scoped through their workspace.
drop policy if exists pw_projects_rw on pw_projects;
create policy pw_projects_rw on pw_projects for all
  using (pw_is_member(workspace_id)) with check (pw_is_member(workspace_id));

-- Graph tables: scoped through the project's workspace.
do $$
declare t text;
begin
  foreach t in array array[
    'pw_requirements','pw_spec_documents','pw_tasks','pw_artifacts','pw_agent_runs'
  ] loop
    execute format('drop policy if exists %I_rw on %I', t, t);
    execute format($f$
      create policy %I_rw on %I for all
        using (pw_is_member((select workspace_id from pw_projects p where p.id = project_id)))
        with check (pw_is_member((select workspace_id from pw_projects p where p.id = project_id)))
    $f$, t, t);
  end loop;
end $$;

-- ----------------------------------------------------------------------------
-- 0004_field_ownership.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- PromptWorkspace Cloud — Milestone 3: per-field conflict ownership
--
-- Row-level LWW silently drops concurrent edits and cannot coexist with an
-- external tracker (Jira owns assignee, PromptWorkspace owns status). We move to
-- field-level merge with declared ownership; this needs per-field version
-- clocks, stored as a jsonb map {field: {updated_at, source}}.
--
-- Additive & backward-compatible: existing rows get an empty field_versions
-- and behave as LWW until their first field-scoped write.

alter table pw_tasks          add column if not exists field_versions jsonb not null default '{}'::jsonb;
alter table pw_requirements   add column if not exists field_versions jsonb not null default '{}'::jsonb;
alter table pw_spec_documents add column if not exists field_versions jsonb not null default '{}'::jsonb;
alter table pw_artifacts      add column if not exists field_versions jsonb not null default '{}'::jsonb;
alter table pw_agent_runs     add column if not exists field_versions jsonb not null default '{}'::jsonb;

-- New PMO fields on tasks, populated by the external-tracker mirror (M5).
alter table pw_tasks add column if not exists assignee text;
alter table pw_tasks add column if not exists sprint   text;

-- ----------------------------------------------------------------------------
-- 0005_tracker_links.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- PromptWorkspace Cloud — Milestone 5: Jira / ClickUp two-way mirror
--
-- A thin sync boundary: mirror only status/assignment/linkage. The AI-native
-- execution graph stays in PromptWorkspace. Direction per field is decided by M3's
-- ownership split (pz out, pmo in).

-- Non-secret per-provider tracker settings live on the workspace.
alter table pw_workspaces add column if not exists integration_config jsonb not null default '{}'::jsonb;

-- Task <-> external issue mapping.
create table if not exists pw_task_links (
    task_id       uuid not null references pw_tasks (id) on delete cascade,
    project_id    uuid not null references pw_projects (id) on delete cascade,
    provider      text not null,                 -- 'jira' | 'clickup'
    external_key  text not null,                 -- e.g. Jira issue key "PZ-42"
    external_url  text not null default '',
    updated_at    timestamptz not null default now(),
    primary key (provider, external_key)
);
create index if not exists idx_pw_task_links_task on pw_task_links (task_id, provider);
create index if not exists idx_pw_task_links_project on pw_task_links (project_id);

-- NOTE: tracker CREDENTIALS (Jira API token, webhook secret) are NOT stored
-- here. They come from the server environment / secret manager, keeping the
-- ADR 0010 §5 "no raw secrets in the cloud DB" posture. This table and
-- integration_config hold only non-secret linkage + settings.

alter table pw_task_links enable row level security;
drop policy if exists pw_task_links_rw on pw_task_links;
create policy pw_task_links_rw on pw_task_links for all
  using (pw_is_member((select workspace_id from pw_projects p where p.id = project_id)))
  with check (pw_is_member((select workspace_id from pw_projects p where p.id = project_id)));

-- ----------------------------------------------------------------------------
-- 0006_grants.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- Grant base table privileges to `authenticated` (RLS then narrows per-row).
--
-- Found by running apps/cloud against a real local Supabase instance for the
-- first time (docs/plans/0004): every prior migration created RLS policies
-- but never granted the underlying table privileges. Supabase's local/hosted
-- bootstrap only grants TRUNCATE/REFERENCES/TRIGGER schema-wide by design —
-- SELECT/INSERT/UPDATE/DELETE are left to each project's own migrations, and
-- RLS policies are silently unreachable without them (Postgres checks the
-- base GRANT before RLS ever runs). Every prior request to a real Supabase
-- project would have failed with `permission denied for table ...` — this
-- was not previously exercised end-to-end.
grant select, insert, update, delete on
  pw_projects,
  pw_requirements,
  pw_spec_documents,
  pw_tasks,
  pw_artifacts,
  pw_agent_runs,
  pw_workspaces,
  pw_workspace_members,
  pw_invitations,
  pw_task_links
to authenticated;

-- Future tables this app creates should get the same treatment automatically.
alter default privileges in schema public
  grant select, insert, update, delete on tables to authenticated;

-- ----------------------------------------------------------------------------
-- 0007_membership_bootstrap.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- Fix a real bootstrap deadlock in the membership RLS policy, found by
-- running apps/cloud against a real local Supabase instance for the first
-- time (docs/plans/0004): `pw_members_write`'s WITH CHECK was
-- `pw_is_admin(workspace_id)` with no exception — but the very first
-- membership row for a workspace (the creator adding themselves as admin,
-- in Repository.create_workspace / SupabaseRepository.add_member) can never
-- satisfy that, because no admin exists yet to satisfy it. Workspace
-- creation was unreachable under enforced RLS. This was invisible until now
-- because `for_user()` (which forwards the caller's JWT so RLS applies) was
-- previously dead code, never called from any route — see app/dependencies.py.
--
-- Mirrors pw_ws_write's own bootstrap escape (`created_by = auth.uid() or
-- pw_is_admin(id)`): allow a workspace's own creator to insert exactly one
-- admin membership row for themselves; any other membership write still
-- requires an existing admin.
--
-- The obvious version of this (an inline `exists (select 1 from
-- pw_workspaces ...)` in the policy) does NOT work: pw_workspaces has its
-- own RLS (`pw_ws_read` requires membership), so a plain subquery run as the
-- `authenticated` role hits the *same* bootstrap deadlock one layer down —
-- it can't see the workspace it's supposed to be checking either. Needs a
-- `security definer` helper (same pattern as pw_is_admin/pw_is_member) to
-- read pw_workspaces without going through RLS.
create or replace function pw_created_workspace(ws uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from pw_workspaces where id = ws and created_by = auth.uid());
$$;

drop policy if exists pw_members_write on pw_workspace_members;
create policy pw_members_write on pw_workspace_members for all
  using (pw_is_admin(workspace_id))
  with check (
    pw_is_admin(workspace_id)
    or (user_id = auth.uid() and role = 'admin' and pw_created_workspace(workspace_id))
  );

-- ----------------------------------------------------------------------------
-- 0008_invitations_rls.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- pw_invitations never had row-level security enabled at all (migration
-- 0003 enabled RLS on every other new table but missed this one — grep
-- confirms no `enable row level security` / policy for it anywhere).
-- Found while verifying apps/cloud against a real local Supabase instance
-- (docs/plans/0004): before 0006_grants.sql, `authenticated` had no base
-- table privileges either, so this was accidentally locked down (but
-- non-functional). After 0006 granted SELECT/INSERT/UPDATE/DELETE broadly,
-- it became a real hole — any authenticated user could read or modify any
-- workspace's invitations (see other workspaces' pending invite tokens,
-- change roles, mark invites accepted, etc). Closing it now, in the same
-- session that opened the gap, rather than shipping 0006 alone.
alter table pw_invitations enable row level security;

-- Manageable (create/revoke/read) by workspace admins.
drop policy if exists pw_invitations_admin on pw_invitations;
create policy pw_invitations_admin on pw_invitations for all
  using (pw_is_admin(workspace_id))
  with check (pw_is_admin(workspace_id));

-- The invited person themselves (matched by email — the invite is
-- addressed to an email, not a user id, since the invitee may not have an
-- account when invited) needs SELECT (accept_invitation reads it by token
-- before the caller is a member) and UPDATE (marking their own invite
-- accepted/expired) — but not INSERT/DELETE, only an admin creates/revokes.
-- Postgres RLS policies take exactly one command in FOR, not a list —
-- hence two policies rather than `for select, update`.
drop policy if exists pw_invitations_invitee_read on pw_invitations;
create policy pw_invitations_invitee_read on pw_invitations for select
  using (email = auth.email());

-- RLS restricts *rows*, not *columns* — `email = auth.email()` alone would
-- let an invitee UPDATE any column of a row they can already reach,
-- including `workspace_id` and `role`. Since app code only ever updates
-- `status` (verified: grep of app/db/supabase_repository.py shows no other
-- column touched by UPDATE), lock this down two ways: a column-level GRANT
-- so only `status` is writable at all regardless of which policy matches,
-- and a row policy that only allows a *pending* invite to move to
-- *accepted*/*expired* — not an admin rewriting it to point at a different
-- workspace/role and then "accepting" their own tampered row. Without both,
-- an authenticated user who has ever received even one invitation (to any
-- workspace, expired or revoked) could rewrite that row's workspace_id and
-- role to an arbitrary target and self-escalate to admin there — a real
-- privilege-escalation gap, caught by review before this ever ran anywhere
-- but a local throwaway test database.
revoke update on pw_invitations from authenticated;
grant update (status) on pw_invitations to authenticated;

drop policy if exists pw_invitations_invitee_update on pw_invitations;
create policy pw_invitations_invitee_update on pw_invitations for update
  using (email = auth.email() and status = 'pending')
  with check (email = auth.email() and status in ('accepted', 'expired'));

-- Second half of the same bug class as 0007: accept_invitation() calls
-- add_member() for the *accepting* user, who is neither already an admin
-- nor the workspace's creator — 0007's bootstrap escape doesn't cover them.
-- Allow a self-membership-insert when a matching accepted invitation exists
-- (accept_invitation marks the invitation accepted before adding the member).
create or replace function pw_has_accepted_invite(ws uuid, r text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from pw_invitations i
    where i.workspace_id = ws
      and i.role = r
      and i.email = auth.email()
      and i.status = 'accepted'
  );
$$;

-- USING needs the same bootstrap/invite-acceptance escape as WITH CHECK, not
-- just WITH CHECK alone: `add_member()` uses `.upsert(on_conflict=...)`, and
-- Postgres's RLS for `INSERT ... ON CONFLICT DO UPDATE` evaluates the
-- UPDATE-side USING clause too — to guarantee RLS would hold *if* the
-- update branch were taken — even when the row is brand new and no actual
-- conflict occurs. Verified directly: the exact same insert that succeeds
-- as a plain INSERT was rejected once routed through ON CONFLICT DO UPDATE,
-- purely because USING (unlike WITH CHECK at the time) had no bootstrap
-- escape. This is documented Postgres behavior, not a bug in Postgres.
create or replace function pw_can_self_add_member(ws uuid, uid uuid, r text) returns boolean
language sql stable security definer set search_path = public as $$
  select uid = auth.uid()
    and (
      (r = 'admin' and pw_created_workspace(ws))
      or pw_has_accepted_invite(ws, r)
    );
$$;

drop policy if exists pw_members_write on pw_workspace_members;
create policy pw_members_write on pw_workspace_members for all
  using (pw_is_admin(workspace_id) or pw_can_self_add_member(workspace_id, user_id, role))
  with check (pw_is_admin(workspace_id) or pw_can_self_add_member(workspace_id, user_id, role));

-- ----------------------------------------------------------------------------
-- 0009_rag.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- PromptWorkspace Cloud — Milestone 9: RAG assistant v1 (plan 0005, ADR 0011)
--
-- v1 embeds only requirements, spec_documents, and tasks (the entities that
-- already carry free text) — no Discussion entity or Artifact content exist
-- yet, so those v1-plan sources are deferred, not silently expanded here.
create extension if not exists vector;

-- Workspace-BYO model connection (chat + embedding). secret_ref is opaque
-- ciphertext produced by app/secrets.py (Fernet, key = RAG_KEY_ENCRYPTION_KEY
-- env var, never in Postgres) — the API never serializes this column back to
-- any client, and no plaintext key material is ever written here.
create table if not exists pw_workspace_model_connections (
    workspace_id       uuid primary key references pw_workspaces (id) on delete cascade,
    provider           text not null,          -- descriptive only: 'openai' | 'ollama' | ...
    base_url           text not null,          -- OpenAI-compatible endpoint the key is BYO for
    model              text not null,          -- chat model
    embed_model        text not null,
    embed_dim          integer not null default 1536,
    secret_ref         text not null,
    daily_token_budget integer not null default 200000,
    created_by         uuid not null,
    created_at         timestamptz not null default now(),
    updated_at         timestamptz not null default now()
);

alter table pw_workspace_model_connections enable row level security;

drop policy if exists pw_wmc_read on pw_workspace_model_connections;
create policy pw_wmc_read on pw_workspace_model_connections
  for select using (pw_is_member(workspace_id));
drop policy if exists pw_wmc_write on pw_workspace_model_connections;
create policy pw_wmc_write on pw_workspace_model_connections
  for all using (pw_is_admin(workspace_id)) with check (pw_is_admin(workspace_id));

-- Chunked, embedded artifact text. Written by the background embed worker via
-- the service-role repository (bypasses RLS like the rest of the sync path);
-- RLS here is member-read defense-in-depth, mirroring pw_tasks etc.
create table if not exists pw_rag_chunks (
    id           uuid primary key default gen_random_uuid(),
    workspace_id uuid not null references pw_workspaces (id) on delete cascade,
    project_id   uuid not null references pw_projects (id) on delete cascade,
    node_type    text not null,      -- 'requirements' | 'spec_documents' | 'tasks'
    node_id      uuid not null,
    chunk_index  integer not null,
    content      text not null,
    embedding    vector(1536) not null,
    updated_at   timestamptz not null default now(),
    unique (node_id, chunk_index)
);

create index if not exists idx_pw_rag_chunks_scope on pw_rag_chunks (workspace_id, project_id);
create index if not exists idx_pw_rag_chunks_embedding
  on pw_rag_chunks using ivfflat (embedding vector_cosine_ops) with (lists = 100);

alter table pw_rag_chunks enable row level security;

drop policy if exists pw_rag_chunks_read on pw_rag_chunks;
create policy pw_rag_chunks_read on pw_rag_chunks
  for select using (pw_is_member(workspace_id));

grant select, insert, update, delete on
  pw_workspace_model_connections, pw_rag_chunks
to authenticated;

-- Retrieval RPC: membership scoping happens at the app layer (require_project
-- gates the caller to a workspace they belong to) *and* here via the explicit
-- workspace_id/project_id predicate — nearest-neighbour search never runs
-- unscoped, per ADR 0011 ("Retrieval is membership-scoped before similarity").
-- Plain (invoker) security: PostgREST calls made with the caller's JWT still
-- go through pw_rag_chunks_read as a second, independent layer.
create or replace function pw_rag_match_chunks(
    p_workspace_id uuid,
    p_project_id uuid,
    p_query_embedding vector(1536),
    p_match_count integer default 8
) returns table (
    node_type text,
    node_id uuid,
    chunk_index integer,
    content text,
    score float
)
language sql stable set search_path = public as $$
  select node_type, node_id, chunk_index, content,
         1 - (embedding <=> p_query_embedding) as score
  from pw_rag_chunks
  where workspace_id = p_workspace_id and project_id = p_project_id
  order by embedding <=> p_query_embedding
  limit p_match_count;
$$;

grant execute on function pw_rag_match_chunks(uuid, uuid, vector, integer) to authenticated;

-- ----------------------------------------------------------------------------
-- 0010_github.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- PromptWorkspace Cloud — Milestone 11: Git-host integration (plan 0005, ADR 0011)
--
-- Two tables, two very different data classes:
--   * pw_pull_requests — PR title/description, real text. ADR 0011 names
--     this an indexable v2 source explicitly (not source code).
--   * pw_code_chunks   — embeddings + (repo, path, sha, line range) ONLY.
--     No `content` column, by construction: code is fetched fresh from the
--     Git host at answer time and discarded (app/api/assistant.py), never
--     persisted here even transiently. This is the literal implementation
--     of "no source code at rest."
--
-- GitHub App credentials (app id, private key, webhook secret) live in the
-- server env (Settings.github_app_*), never in Postgres — same rule as
-- jira_api_token. Per-workspace config (installation_id, repo,
-- default_branch, project_id) is non-secret and lives on
-- pw_workspaces.integration_config->'github' (existing jsonb column, same
-- pattern the Jira/ClickUp integration already uses) — no new column or
-- table needed for it.

create table if not exists pw_pull_requests (
    id           text primary key,  -- deterministic: pr-{project_id}-{number}
    project_id   uuid not null references pw_projects (id) on delete cascade,
    number       integer not null,
    title        text not null,
    body         text not null default '',
    html_url     text not null,
    head_sha     text not null,
    task_id      uuid references pw_tasks (id) on delete set null,
    merged       boolean not null default false,
    deleted_at   timestamptz,
    updated_at   timestamptz not null default now(),
    unique (project_id, number)
);

create index if not exists idx_pw_pull_requests_project on pw_pull_requests (project_id);

alter table pw_pull_requests enable row level security;

drop policy if exists pw_pull_requests_read on pw_pull_requests;
create policy pw_pull_requests_read on pw_pull_requests
  for select using (
    exists (
      select 1 from pw_projects p
      where p.id = pw_pull_requests.project_id and pw_is_member(p.workspace_id)
    )
  );

create table if not exists pw_code_chunks (
    id           uuid primary key default gen_random_uuid(),
    workspace_id uuid not null references pw_workspaces (id) on delete cascade,
    project_id   uuid not null references pw_projects (id) on delete cascade,
    repo         text not null,      -- "owner/name"
    path         text not null,
    sha          text not null,
    start_line   integer not null,
    end_line     integer not null,
    chunk_index  integer not null,
    embedding    vector(1536) not null,
    updated_at   timestamptz not null default now(),
    unique (project_id, repo, path, chunk_index)
);

create index if not exists idx_pw_code_chunks_scope on pw_code_chunks (workspace_id, project_id);
create index if not exists idx_pw_code_chunks_path on pw_code_chunks (project_id, repo, path);
create index if not exists idx_pw_code_chunks_embedding
  on pw_code_chunks using ivfflat (embedding vector_cosine_ops) with (lists = 100);

alter table pw_code_chunks enable row level security;

drop policy if exists pw_code_chunks_read on pw_code_chunks;
create policy pw_code_chunks_read on pw_code_chunks
  for select using (pw_is_member(workspace_id));

grant select, insert, update, delete on pw_pull_requests, pw_code_chunks to authenticated;

-- Membership-scoped before similarity (ADR 0011), same shape as
-- pw_rag_match_chunks — the explicit workspace_id/project_id predicate runs
-- before the nearest-neighbour search, independent of RLS.
create or replace function pw_code_match_chunks(
    p_workspace_id uuid,
    p_project_id uuid,
    p_query_embedding vector(1536),
    p_match_count integer default 8
) returns table (
    repo text,
    path text,
    sha text,
    start_line integer,
    end_line integer,
    score float
)
language sql stable set search_path = public as $$
  select repo, path, sha, start_line, end_line,
         1 - (embedding <=> p_query_embedding) as score
  from pw_code_chunks
  where workspace_id = p_workspace_id and project_id = p_project_id
  order by embedding <=> p_query_embedding
  limit p_match_count;
$$;

grant execute on function pw_code_match_chunks(uuid, uuid, vector, integer) to authenticated;

-- ----------------------------------------------------------------------------
-- 0011_discussions.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- PromptWorkspace Cloud — Milestone 12: Discussion entity (plan 0005, ADR 0011)
--
-- Comments threaded on any graph node. Unlike pw_tasks (row-level split
-- ownership: status is pz-only, assignee is pmo-only), a discussion row is
-- created wholesale by one source or the other — pz (web/desktop) and pmo
-- (Jira comment mirror, M12) never fight over the same row's fields, they
-- each create their own rows. field_versions/FIELD_AUTHORITY still apply
-- ("shared") for the same-row-edited-twice case (e.g. re-syncing your own
-- comment), consistent with every other graph table.
--
-- Built fresh here (not editing 0001/0002/0003/0004) with deleted_at and
-- field_versions already included, rather than the historical
-- init-then-backfill sequence those migrations show — this table didn't
-- exist when that sequence of gaps was being closed.

create table if not exists pw_discussions (
    id                uuid primary key default gen_random_uuid(),
    project_id        uuid not null references pw_projects (id) on delete cascade,
    parent_node_type  text not null,   -- 'requirements' | 'spec_documents' | 'tasks' | 'artifacts'
    parent_node_id    uuid not null,
    author            uuid not null,
    body              text not null,
    source            text not null default 'pz' check (source in ('pz', 'pmo')),
    field_versions    jsonb not null default '{}'::jsonb,
    deleted_at        timestamptz,
    updated_at        timestamptz not null default now()
);

create index if not exists idx_pw_discussions_project on pw_discussions (project_id);
create index if not exists idx_pw_discussions_parent on pw_discussions (parent_node_type, parent_node_id);
create index if not exists idx_pw_discussions_live on pw_discussions (project_id) where deleted_at is null;

alter table pw_discussions enable row level security;

-- Same shape as the do-block in 0003_auth_workspaces.sql that scopes every
-- other graph table through the project's workspace — written directly here
-- rather than re-running that migration's loop against an old file.
drop policy if exists pw_discussions_rw on pw_discussions;
create policy pw_discussions_rw on pw_discussions for all
  using (pw_is_member((select workspace_id from pw_projects p where p.id = project_id)))
  with check (pw_is_member((select workspace_id from pw_projects p where p.id = project_id)));

grant select, insert, update, delete on pw_discussions to authenticated;

-- RAG opt-in for pmo-mirrored (Jira) comments (ADR 0011: third-party content
-- defaults OUT; pz-native discussions are always in). A typed column on the
-- workspace, not another integration_config key.
alter table pw_workspaces add column if not exists rag_index_pmo_discussions boolean not null default false;

-- ----------------------------------------------------------------------------
-- 0012_member_email.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- PromptWorkspace Cloud — Milestone 13: denormalize member email
--
-- pw_workspace_members only stored user_id (auth.users.id), forcing the web
-- UI to render a raw UUID for "who is this member" — auth.users itself is
-- only readable by service_role, so a join isn't an option for the
-- anon/authenticated roles this app queries as. Denormalize the email onto
-- the membership row instead, populated at insert time (create_workspace /
-- accept_invitation already know it — from the session or the invitation).
-- Existing rows backfill to null; the UI falls back to the id for those.

alter table pw_workspace_members add column if not exists email text;

-- ----------------------------------------------------------------------------
-- 0013_documents.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- PromptWorkspace Cloud — Milestone 0 (plan 0007): project knowledge base.
--
-- Uploaded artifacts (PRD PDFs, Markdown) become a first-class `documents`
-- graph node, riding the same RAG rails as every other node_type (M9):
-- extracted text is chunked + embedded into pw_rag_chunks once extraction
-- succeeds. Unlike code_file (M11), extracted text IS persisted here — these
-- are business documents, not source code, so ADR 0011's "no source at rest"
-- rule doesn't apply.
create table if not exists pw_documents (
    id             uuid primary key default gen_random_uuid(),
    workspace_id   uuid not null references pw_workspaces (id) on delete cascade,
    project_id     uuid not null references pw_projects (id) on delete cascade,
    title          text not null,
    mime           text not null,
    storage_ref    text not null,      -- opaque path into Supabase Storage
    source_kind    text not null default 'upload',  -- 'upload' | future: 'figma-mcp'
    extract_method text,               -- 'passthrough' | 'text_layer' | 'ocr', null until extracted
    status         text not null default 'pending',  -- 'pending' | 'extracted' | 'failed'
    extracted_text text,
    created_by     uuid not null,
    created_at     timestamptz not null default now(),
    updated_at     timestamptz not null default now(),
    deleted_at     timestamptz
);

create index if not exists idx_pw_documents_scope on pw_documents (workspace_id, project_id);

alter table pw_documents enable row level security;

drop policy if exists pw_documents_read on pw_documents;
create policy pw_documents_read on pw_documents
  for select using (pw_is_member(workspace_id));
drop policy if exists pw_documents_write on pw_documents;
create policy pw_documents_write on pw_documents
  for all using (pw_is_member(workspace_id)) with check (pw_is_member(workspace_id));

grant select, insert, update, delete on pw_documents to authenticated;

comment on column pw_rag_chunks.node_type is
  'requirements | spec_documents | tasks | pull_requests | discussions | documents';

-- Supabase Storage: one bucket for uploaded document originals, RLS-scoped by
-- the same membership function used everywhere else. Objects are stored
-- under `<workspace_id>/<document_id>/<filename>` so the workspace segment of
-- the path can be checked directly in the policy without a table join.
insert into storage.buckets (id, name, public)
  values ('pw-documents', 'pw-documents', false)
  on conflict (id) do nothing;

drop policy if exists pw_documents_storage_read on storage.objects;
create policy pw_documents_storage_read on storage.objects
  for select using (
    bucket_id = 'pw-documents'
    and pw_is_member((storage.foldername(name))[1]::uuid)
  );

drop policy if exists pw_documents_storage_write on storage.objects;
create policy pw_documents_storage_write on storage.objects
  for insert with check (
    bucket_id = 'pw-documents'
    and pw_is_member((storage.foldername(name))[1]::uuid)
  );

-- ----------------------------------------------------------------------------
-- 0014_generation_runs.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- PromptWorkspace Cloud — Milestone 1 (plan 0007): generation audit + cost
-- accounting. Not part of the task graph itself — the generated artifact
-- lands as a Requirement/SpecDocument/Task via the existing sync/upsert
-- path (app/api/generation.py); this table only records that a generation
-- happened, on what model, and how many tokens it spent.
create table if not exists pw_generation_runs (
    id                uuid primary key default gen_random_uuid(),
    workspace_id      uuid not null references pw_workspaces (id) on delete cascade,
    project_id        uuid not null references pw_projects (id) on delete cascade,
    stage             text not null,   -- 'constitution' | 'specify' | 'plan' | 'tasks'
    model_source      text not null default 'byo',  -- 'byo' | future: 'managed' (M2)
    model             text not null,
    status            text not null default 'running',  -- 'running' | 'succeeded' | 'failed'
    prompt_tokens     integer not null default 0,
    completion_tokens integer not null default 0,
    created_at        timestamptz not null default now()
);

create index if not exists idx_pw_generation_runs_scope on pw_generation_runs (workspace_id, project_id);

alter table pw_generation_runs enable row level security;

drop policy if exists pw_generation_runs_read on pw_generation_runs;
create policy pw_generation_runs_read on pw_generation_runs
  for select using (pw_is_member(workspace_id));

drop policy if exists pw_generation_runs_write on pw_generation_runs;
create policy pw_generation_runs_write on pw_generation_runs
  for insert with check (pw_is_member(workspace_id));

drop policy if exists pw_generation_runs_update on pw_generation_runs;
create policy pw_generation_runs_update on pw_generation_runs
  for update using (pw_is_member(workspace_id)) with check (pw_is_member(workspace_id));

grant select, insert, update, delete on pw_generation_runs to authenticated;

-- ----------------------------------------------------------------------------
-- 0015_stage_model_routing.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- PromptWorkspace Cloud — Milestone 3 (plan 0007): stage routing table.
--
-- Overrides the hard-coded default (constitution/specify/tasks -> managed,
-- plan -> byo — see app/generation/routing.py::DEFAULT_STAGE_ROUTING,
-- removed 2026-07-25, see ADR 0013's update note) per
-- workspace (project_id null) or per project (project_id set). Resolution
-- order is project -> workspace -> default; app/generation/routing.py owns
-- that logic, this table only stores the overrides that exist.
--
-- project_id is nullable and NULLs are never equal to each other in a
-- Postgres unique constraint, so a naive UNIQUE(workspace_id, project_id,
-- stage) would silently allow duplicate workspace-level rows (project_id
-- IS NULL) for the same stage. app/db/repository.py's upsert deletes any
-- existing matching row before inserting instead of relying on ON CONFLICT,
-- so no unique constraint is declared here — just an index for lookups.
create table if not exists pw_stage_model_routing (
    id           uuid primary key default gen_random_uuid(),
    workspace_id uuid not null references pw_workspaces (id) on delete cascade,
    project_id   uuid references pw_projects (id) on delete cascade,
    stage        text not null,  -- 'constitution' | 'specify' | 'plan' | 'tasks'
    model_source text not null,  -- 'byo' | 'managed'
    model        text,           -- optional specific model name override
    created_at   timestamptz not null default now(),
    updated_at   timestamptz not null default now()
);

create index if not exists idx_pw_stage_model_routing_lookup
  on pw_stage_model_routing (workspace_id, project_id, stage);

alter table pw_stage_model_routing enable row level security;

drop policy if exists pw_stage_model_routing_read on pw_stage_model_routing;
create policy pw_stage_model_routing_read on pw_stage_model_routing
  for select using (pw_is_member(workspace_id));
drop policy if exists pw_stage_model_routing_write on pw_stage_model_routing;
create policy pw_stage_model_routing_write on pw_stage_model_routing
  for all using (pw_is_admin(workspace_id)) with check (pw_is_admin(workspace_id));

grant select, insert, update, delete on pw_stage_model_routing to authenticated;

-- ----------------------------------------------------------------------------
-- 0016_rag_chunk_embed_model.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- PromptWorkspace Cloud — Milestone 1 (plan 0008): track which embed model
-- produced each chunk, so a project's chunks can be checked for homogeneity
-- before a query runs against them. pw_rag_chunks.embedding is a fixed
-- vector(1536) column — switching a workspace's embedding source (BYO <->
-- managed, plan 0007 M2) without reindexing would otherwise silently compare
-- vectors from two different models. app/api/assistant.py checks this
-- column against the resolved query's embed model and rejects with a clear
-- "reindex required" error on mismatch, rather than returning garbage
-- similarity scores.
alter table pw_rag_chunks add column if not exists embed_model text not null default '';

-- ----------------------------------------------------------------------------
-- 0017_task_assigned_user.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- PromptWorkspace Cloud — task assignment to workspace members (ADR 0016)
--
-- A pz-owned assignee distinct from the pmo `assignee` (a tracker display
-- name). Holds a workspace member's user_id; the app sets it via
-- PATCH /projects/{id}/tasks/{tid}/assignment, merged source="pz".
-- Additive & backward-compatible: existing rows default to NULL (unassigned).

alter table pw_tasks add column if not exists assigned_user_id text;

-- ----------------------------------------------------------------------------
-- 0018_project_lifecycle.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- PromptWorkspace Cloud — project lifecycle status + repo linkage (cloud
-- Planner UI, sub-project A). Tracks the planning -> pending_tech_review ->
-- tech_review -> repo_created handoff between business user, Tech Lead, and
-- desktop app (docs/superpowers/specs/2026-07-25-cloud-planner-ui-design.md).
-- Additive & backward-compatible: existing rows default to 'planning'.

alter table pw_projects add column if not exists lifecycle_status text not null default 'planning';
alter table pw_projects add column if not exists repo_url text;
alter table pw_projects add column if not exists repo_default_branch text;

-- ----------------------------------------------------------------------------
-- 0019_stage_documents.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- PromptWorkspace Cloud — stage_documents: raw-markdown side store for
-- Planner stages (constitution/specify/plan/tasks), independent of the
-- graph-entity persistence (Requirement/SpecDocument/Task). Lets the
-- Planner tab show a Raw|Preview editor with edits that survive reload and
-- feed into RAG chat (docs/superpowers/specs/2026-07-26-planner-markdown-
-- editor-design.md). One row per (project_id, stage) — a fresh generation
-- or a manual edit overwrites the existing row for that stage, no history.

create table if not exists pw_stage_documents (
    id uuid primary key default gen_random_uuid(),
    workspace_id uuid not null references pw_workspaces (id),
    project_id uuid not null references pw_projects (id),
    stage text not null check (stage in ('constitution', 'specify', 'plan', 'tasks')),
    content text not null default '',
    created_by uuid,
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    unique (project_id, stage)
);

create index if not exists idx_pw_stage_documents_scope on pw_stage_documents (workspace_id, project_id) where deleted_at is null;

alter table pw_stage_documents enable row level security;

drop policy if exists pw_stage_documents_read on pw_stage_documents;
create policy pw_stage_documents_read on pw_stage_documents
  for select using (pw_is_member(workspace_id));
drop policy if exists pw_stage_documents_write on pw_stage_documents;
create policy pw_stage_documents_write on pw_stage_documents
  for all using (pw_is_member(workspace_id)) with check (pw_is_member(workspace_id));

grant select, insert, update, delete on pw_stage_documents to authenticated;

-- ----------------------------------------------------------------------------
-- 0020_repo_webhooks.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- 0020 — per-repository webhook bindings, replacing the GitHub App's
-- platform-wide signing secret.
--
-- GitHub auth moved from one platform App to a per-workspace fine-grained PAT
-- (ADR 0017 amendment), which removes the shared `GITHUB_WEBHOOK_SECRET`. Each
-- repository the cloud creates now gets its own randomly generated secret,
-- registered on the repo's webhook and stored here as ciphertext
-- (app/secrets.py) — never plaintext, same rule as model-connection keys.
--
-- `repo_full_name` is the PRIMARY KEY, not merely indexed. That is the point:
-- the old routing scanned workspace rows for a client-supplied `repo` string
-- and took the first match, so two workspaces could claim the same repo and
-- one would silently intercept the other's deliveries (issue #3). A repo now
-- maps to exactly one project, and only the cloud writes the binding — at the
-- moment it creates the repo.

create table if not exists pw_repo_webhooks (
    repo_full_name text primary key,
    project_id uuid not null references pw_projects (id),
    workspace_id uuid not null references pw_workspaces (id),
    secret_ref text not null,
    created_at timestamptz not null default now()
);

create index if not exists idx_pw_repo_webhooks_project on pw_repo_webhooks (project_id);

alter table pw_repo_webhooks enable row level security;

-- Deliberately no `authenticated` grant and no permissive policy: the webhook
-- route runs unauthenticated (GitHub is the caller) on the service key, and
-- `secret_ref` must never be reachable from a browser session. Members read
-- nothing here; there is nothing here a member needs.
drop policy if exists pw_repo_webhooks_service_only on pw_repo_webhooks;

revoke all on pw_repo_webhooks from authenticated;

-- The old GitHub App config shape is not migrated. A workspace that had an
-- installation must reconnect with a PAT in workspace settings; leaving the
-- stale `installation_id` in place would read as "connected" while every call
-- path fails. app/integrations/github_auth.py::github_config treats a config
-- without `secret_ref` as not connected, which makes that explicit.
update pw_workspaces
   set integration_config = integration_config - 'github'
 where integration_config ? 'github'
   and not (integration_config -> 'github' ? 'secret_ref');

-- ----------------------------------------------------------------------------
-- 0021_repo_webhooks_anon_revoke.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- 0021 — finish 0020's posture on pw_repo_webhooks: `anon` too, not just
-- `authenticated`.
--
-- 0020 revoked the table from `authenticated` and left `anon` alone, which
-- 0006's `alter default privileges` had already granted select/insert/update/
-- delete. Nothing leaks today — the table has RLS enabled and no policy, so
-- every non-bypassing role is denied per row regardless of its grants — but a
-- table whose whole point is holding webhook signing secrets should not be one
-- accidental permissive policy away from being world-readable. The grant and
-- the intent should agree.
--
-- Writers are unaffected: the only writer is app/api/sync.py's repo-creation
-- step and the only reader is the inbound webhook route, both of which run on
-- the service key (service_role bypasses RLS and keeps its grants).
revoke all on pw_repo_webhooks from anon;

-- ----------------------------------------------------------------------------
-- 0022_policy_scope.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- 0022 — Policy Scope: a project's declared compliance/regulatory frame
-- (built-in template IDs + free-text custom scope), injected server-side
-- into constitution/specify/plan/tasks generation and seeded into the repo
-- at tech-review exit. See app/models/schemas.py::PolicyScope and
-- app/policies/registry.py.
-- Additive & backward-compatible: existing rows default to null (never
-- selected), which the generation and repo-seed paths treat as empty scope.

alter table pw_projects add column if not exists policy_scope jsonb;

-- ----------------------------------------------------------------------------
-- 0023_configurable_embed_dim.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- 0023 — stop hardcoding the embedding width at 1536.
--
-- pw_rag_chunks.embedding, pw_code_chunks.embedding, and both
-- pw_*_match_chunks(p_query_embedding vector(1536), …) signatures were a
-- fixed vector(1536) column/parameter. That ceiling excludes every strong
-- open multilingual encoder and every free local option verified during
-- this project (BGE-m3 1024, Jina v3 1024, KaLM-embedding-multilingual
-- v2.5 896 — its MRL truncates down only, never up — and every embedding
-- model in Ollama's catalogue at 1024 or smaller). The only free 1536
-- model found (Alibaba-NLP/gte-Qwen2-1.5B-instruct) isn't in Ollama. For a
-- deployment whose content is mixed Thai/English, that ceiling is a real
-- retrieval-quality regression, not a cosmetic one.
--
-- `embed_dim` was already threaded through app/config.py, app/models/
-- schemas.py, app/db/repository.py and app/db/supabase_repository.py
-- (plan 0008 M1) — only the DDL was still a literal 1536.
--
-- WHY A PSQL VARIABLE, NOT A NEW FIXED CONSTANT
-- A migration file cannot read this service's runtime config, and there is
-- no single dimension that is "right" for every deployer — it depends on
-- which embedding model they actually run. So this migration takes the
-- width as a deploy-time parameter instead of picking a new hardcoded
-- number (which would just move the ceiling, not remove it):
--
--     psql "$SUPABASE_DB_URL" -v ON_ERROR_STOP=1 -v embed_dim=1024 -f migrations/0023_configurable_embed_dim.sql
--
-- Pick the number to match the `embed_dim` you configure on the workspace
-- model connection (POST /workspaces/{id}/model-connection) — e.g. 1024 for
-- BGE-m3 or Jina v3, 896 for KaLM-embedding-multilingual v2.5. There is no
-- default on purpose: silently falling back to 1536 would resurrect the
-- exact ceiling this migration exists to remove, so applying it without
-- -v embed_dim=<N> aborts loudly below instead of guessing. `-v
-- ON_ERROR_STOP=1` is required too — psql's own default for a scripted -f
-- run is to log an error and keep going with exit code 0, which would
-- silently skip straight to the destructive statements below instead of
-- actually stopping on the guard.
--
-- This migration is therefore NOT part of the plain
-- `for f in migrations/00*.sql; do psql ... -f "$f"; done` loop — apply
-- everything up to 0022 that way, run this one by hand with -v embed_dim=N,
-- then resume the loop for anything after it. See docs/DEPLOYMENT.md and
-- apps/cloud/README.md.
--
-- migration-runner: requires-vars=embed_dim
-- (read by scripts/migrate.py, which refuses — before opening a connection
-- — to apply this file without a matching `--var embed_dim=<N>`. The \if
-- guard a few lines down is the same protection for anyone who runs this
-- file with plain psql instead of the runner; the two are independent on
-- purpose, so neither path can silently skip the check.)
--
-- WHY DESTRUCTIVE, NOT AN IN-PLACE WIDEN/NARROW
-- A vector(1536) value cannot be reinterpreted as a vector(N) value for any
-- N != 1536 — the numbers at each position mean something only in the
-- geometry of the model that produced them, there is no valid cast. Any
-- deployment that has already embedded chunks under vector(1536) MUST lose
-- those vectors to change width; there is no non-destructive path. This
-- migration does not pretend otherwise: it deletes every existing chunk
-- row before narrowing the column, rather than leaving stale 1536-wide
-- rows sitting in a column that now claims a different width (which would
-- either fail the ALTER outright or, worse, leave a column Postgres
-- refuses to let old and new rows coexist in).
--
-- What is NOT lost: pw_rag_chunks/pw_code_chunks are a derived cache, not
-- a source of truth. Requirements/spec_documents/tasks text still lives on
-- those entities; GitHub code was never persisted here in the first place
-- (ADR 0011 "no source code at rest" — pw_code_chunks has no `content`
-- column, only refs). Losing embeddings therefore costs re-embedding
-- spend and a temporary grounding gap, not content. The operator still
-- MUST reindex afterward (POST /workspaces/{id}/assistant/reindex) — until
-- they do, every content/mixed chat question falls back to "no indexed
-- content" (ungrounded, but never silently wrong) via the existing
-- app/api/assistant.py retrieval-transparency path.
\if :{?embed_dim}
\else
do $$ begin
  raise exception 'embed_dim is not set. This migration changes a destructive, fixed-width vector column and refuses to guess. Re-run as: psql "$SUPABASE_DB_URL" -v ON_ERROR_STOP=1 -v embed_dim=<N> -f migrations/0023_configurable_embed_dim.sql -- where <N> matches the embed_dim of the model connection you will configure (e.g. 1024 for BGE-m3 / Jina v3, 896 for KaLM-embedding-multilingual v2.5).';
end $$;
\endif

-- [build_baseline.py] top-level begin; removed: the runner wraps this whole file.

-- Existing embeddings cannot survive a width change (see above) — wipe them
-- before touching the column so no row is ever left claiming a width the
-- column no longer has. Everything else on these rows (content, embed
-- model bookkeeping, code-chunk path/sha refs) is either re-derivable by
-- reindexing or, for code, was never stored here to begin with.
delete from pw_rag_chunks;
delete from pw_code_chunks;

-- Dropping the column takes its ivfflat index (idx_pw_rag_chunks_embedding)
-- with it; re-added below at the new width.
alter table pw_rag_chunks drop column embedding;
alter table pw_rag_chunks add column embedding vector(:embed_dim) not null;

create index idx_pw_rag_chunks_embedding
  on pw_rag_chunks using ivfflat (embedding vector_cosine_ops) with (lists = 100);

alter table pw_code_chunks drop column embedding;
alter table pw_code_chunks add column embedding vector(:embed_dim) not null;

create index idx_pw_code_chunks_embedding
  on pw_code_chunks using ivfflat (embedding vector_cosine_ops) with (lists = 100);

-- CREATE OR REPLACE keeps the function's OID (and its existing GRANT), so
-- this changes the parameter's width without needing to drop it first —
-- Postgres matches function identity on the parameter's base type (vector),
-- not its typmod, so this really is a REPLACE, not a rename-in-disguise.
create or replace function pw_rag_match_chunks(
    p_workspace_id uuid,
    p_project_id uuid,
    p_query_embedding vector(:embed_dim),
    p_match_count integer default 8
) returns table (
    node_type text,
    node_id uuid,
    chunk_index integer,
    content text,
    score float
)
language sql stable set search_path = public as $$
  select node_type, node_id, chunk_index, content,
         1 - (embedding <=> p_query_embedding) as score
  from pw_rag_chunks
  where workspace_id = p_workspace_id and project_id = p_project_id
  order by embedding <=> p_query_embedding
  limit p_match_count;
$$;

grant execute on function pw_rag_match_chunks(uuid, uuid, vector, integer) to authenticated;

create or replace function pw_code_match_chunks(
    p_workspace_id uuid,
    p_project_id uuid,
    p_query_embedding vector(:embed_dim),
    p_match_count integer default 8
) returns table (
    repo text,
    path text,
    sha text,
    start_line integer,
    end_line integer,
    score float
)
language sql stable set search_path = public as $$
  select repo, path, sha, start_line, end_line,
         1 - (embedding <=> p_query_embedding) as score
  from pw_code_chunks
  where workspace_id = p_workspace_id and project_id = p_project_id
  order by embedding <=> p_query_embedding
  limit p_match_count;
$$;

grant execute on function pw_code_match_chunks(uuid, uuid, vector, integer) to authenticated;

-- Guard-gap close (app/api/assistant.py): under the old fixed vector(1536)
-- column, a per-chunk dimension mismatch was unreachable — every chunk was
-- 1536-wide by construction, so the existing embed_model_mismatch check
-- (migration 0016) was the only guard that could ever fire. Now that width
-- is a deploy-time choice, two connections can share an embed_model name
-- and still disagree on dimension (e.g. an MRL-truncated width configured
-- differently), and that mismatch is worse than a name mismatch — the
-- stored vectors are not even the same shape as the query vector. This
-- column lets the app check dimension the same way it already checks
-- model name, instead of only finding out via a query-time pgvector error.
alter table pw_rag_chunks add column if not exists embed_dim integer not null default 0;

-- [build_baseline.py] top-level commit; removed: the runner wraps this whole file.

\echo pw_rag_chunks / pw_code_chunks are now vector(:embed_dim). All prior chunks were deleted — run POST /workspaces/{id}/assistant/reindex (or reindex each project) before the assistant can ground content/mixed answers again.

-- ----------------------------------------------------------------------------
-- 0025_task_status_indexes.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- 0025 — indexes for the task-status write and the assigned-task read
--
-- WHY
-- ADR 0020 moves authority for the task graph to the cloud and narrows what a
-- developer client writes upward to three things, two of which land here: a
-- task's status, and the commit that evidences it. Two new access paths follow,
-- and neither is served by the indexes 0001 and 0017 created.
--
--   pw_artifacts_task_commit_uniq
--     The git-driven caller re-sends a commit whenever its local cache is
--     dropped or a repo is re-cloned, so `upsert_task_artifact` replaying is
--     the expected case. The repository does a select-then-insert, which is
--     racy on its own; this partial unique index is what actually makes the
--     write idempotent. Partial (`where commit_sha is not null`) because a
--     PR or doc artifact carries no sha and several of them per task is
--     legitimate — only sha-bearing rows are claiming "this exact commit".
--
--   idx_pw_tasks_assigned_user
--     `GET /me/tasks` filters by assigned_user_id across every project the
--     caller belongs to. 0001 indexed (project_id) and (project_id,
--     updated_at); 0017 added assigned_user_id with no index at all, because
--     its only reader at the time was a per-project keyhole pull. Partial,
--     since the overwhelming majority of rows are unassigned.
--
-- SAFETY
-- Both statements are `if not exists` and neither rewrites a table. The unique
-- index can fail on a database that already holds duplicate (task_id,
-- commit_sha) rows — that is the point. If it does, dedupe first:
--
--   delete from pw_artifacts a using pw_artifacts b
--    where a.task_id = b.task_id and a.commit_sha = b.commit_sha
--      and a.commit_sha is not null and a.id > b.id;
--
-- Apply with the runner in migrations/migrate.py (docs/DEPLOYMENT.md §2.2).

create unique index if not exists pw_artifacts_task_commit_uniq
    on pw_artifacts (task_id, commit_sha)
    where commit_sha is not null;

create index if not exists idx_pw_tasks_assigned_user
    on pw_tasks (assigned_user_id)
    where assigned_user_id is not null;

-- ----------------------------------------------------------------------------
-- 0026_deployments.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- 0026 — Deployment templates: a project's selected deploy pipeline, and the
-- deployments its own CI reports back (ADR 0021).
--
-- Apply with scripts/migrate.py; never edit this file once applied — the
-- pw_schema_migrations ledger (0024) checksums it and reports drift.
--
-- Two additive columns on pw_projects, mirroring 0022's policy_scope:
--
--   deployment_config  the Tech Lead's frozen INPUT   {template_id}
--   deployment_state   the server-written CURRENT VIEW {state, url, ...}
--
-- Separate on purpose: different lifetimes (config freezes at repo_created,
-- state mutates forever), different writers (a member PATCH versus the
-- signed webhook route), and different authorization. One column would put
-- those two writers in a race for no benefit.
--
-- deployment_state duplicates the newest pw_deployments row. That is the same
-- trade repo_url already makes: GET /projects backs the workspace project
-- list and the engine roster projection, and neither can afford a join or an
-- N+1 to answer "is this project live, and where".

alter table pw_projects add column if not exists deployment_config jsonb;
alter table pw_projects add column if not exists deployment_state jsonb;

-- One row per deploy. NOT secret-bearing: URLs, states, commit shas and run
-- links only. The provider credential lives encrypted (Fernet, app/secrets.py)
-- in pw_workspaces.integration_config, exactly like the GitHub PAT, and never
-- reaches this table.
create table if not exists pw_deployments (
    id uuid primary key default gen_random_uuid(),
    workspace_id uuid not null references pw_workspaces (id),
    project_id uuid not null references pw_projects (id),
    provider text not null,
    template_id text not null,
    -- Idempotency key, and the reason for the unique constraint below: one
    -- deploy emits several deliveries (in_progress -> success), so without a
    -- stable key each would insert a duplicate instead of updating.
    external_key text not null,
    state text not null,
    url text,
    commit_sha text,
    ref text,
    run_url text,
    error_code text,
    error_message text,
    -- Measured by a server-side HEAD after a successful deploy: allow | deny
    -- | unknown. A browser cannot read a cross-origin response header, so
    -- this is the only place the answer can come from.
    frame_policy text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    unique (project_id, external_key)
);

create index if not exists idx_pw_deployments_project_created
    on pw_deployments (project_id, created_at desc);

alter table pw_deployments enable row level security;

drop policy if exists pw_deployments_read on pw_deployments;
create policy pw_deployments_read on pw_deployments
  for select using (pw_is_member(workspace_id));

-- SELECT only, deliberately — a third posture, between 0019 (members read and
-- write) and 0020 (no grant at all). Every row here is written by the
-- unauthenticated, HMAC-verified webhook route, which runs on the service key
-- (app/dependencies.py::get_repository returns the unscoped repository when a
-- request carries no Authorization header, and GitHub sends none). No member
-- ever authors a deployment, so no member needs insert/update/delete. But
-- members do legitimately read their own project's deploy history, which is
-- why this is not the 0020 no-grant posture.
grant select on pw_deployments to authenticated;

-- ----------------------------------------------------------------------------
-- 0027_deployment_tasks.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- 0027 — Which tasks are in which build (ADR 0023 decision 4).
--
-- Apply with scripts/migrate.py; never edit this file once applied — the
-- pw_schema_migrations ledger (0024) checksums it and reports drift.
--
-- Frozen at terminal state rather than derived on read, and that is the whole
-- decision. The task set for a build is computed from the commits between it
-- and the previous successful build; a force-push, a task reassignment or a
-- later edit would silently rewrite the history of what a stakeholder
-- reviewed last Tuesday if this were a view.
--
-- `position` preserves the order the resolver produced (task order within the
-- graph), so the Preview tab's "what's in this build" list reads the same way
-- twice.

create table if not exists pw_deployment_tasks (
    deployment_id uuid not null references pw_deployments (id) on delete cascade,
    task_id uuid not null,
    position integer not null default 0,
    created_at timestamptz not null default now(),
    primary key (deployment_id, task_id)
);

create index if not exists idx_pw_deployment_tasks_deployment
    on pw_deployment_tasks (deployment_id, position);

-- No FK to pw_tasks: a task deleted after a build shipped must not take the
-- record of what shipped with it. The read path resolves titles from the
-- graph and simply omits a task it can no longer find.

alter table pw_deployment_tasks enable row level security;

drop policy if exists pw_deployment_tasks_read on pw_deployment_tasks;
-- Membership is checked through the parent deployment: every row here belongs
-- to exactly one deployment, and pw_deployments already carries workspace_id.
create policy pw_deployment_tasks_read on pw_deployment_tasks
  for select using (
    exists (
      select 1 from pw_deployments d
      where d.id = pw_deployment_tasks.deployment_id and pw_is_member(d.workspace_id)
    )
  );

-- SELECT only, matching 0026's posture: every row is written by the
-- HMAC-verified webhook path running on the service key. No member authors an
-- attribution, but members legitimately read their own project's.
grant select on pw_deployment_tasks to authenticated;

-- ----------------------------------------------------------------------------
-- 0028_project_repo_id.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- 0028 — persist the GitHub repository this project actually created (finding
-- 9, docs/cloud-codebase-review-2026-09-06.md). `repo_id` is GitHub's stable
-- numeric repository id, immutable across a rename or transfer — unlike
-- `repo_url`/`full_name`, which a collision can share with an unrelated
-- repository. Written once, at the same step that first writes `repo_url`
-- (apps/cloud/app/api/sync.py::create_repository), before the lifecycle
-- flips to repo_created. Nullable: every project created before this
-- migration has a repo_url with no recorded id.

alter table pw_projects add column if not exists repo_id bigint;

-- ----------------------------------------------------------------------------
-- 0029_repo_webhook_registration_state.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- 0029 — durable registration state for per-repository webhook secrets.
--
-- A binding is written before GitHub registration so the first delivery cannot
-- race its local key.  `pending` prevents another request from treating that
-- provisional secret as confirmed while the first request is still registering
-- it. Existing rows predate this state and are treated as already confirmed.

alter table pw_repo_webhooks
    add column if not exists registration_state text not null default 'confirmed'
        check (registration_state in ('pending', 'confirmed')),
    add column if not exists registration_owner uuid;


-- ----------------------------------------------------------------------------
-- 0030_graph_tables_grant_service_role.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- 0030 — name the server's own role on the graph tables, before anything
-- depends on it (docs/plans/0014-row-level-security-parity.md, Option A).
--
-- This is the FIRST of a deliberate pair. It only ever *adds* a privilege, to
-- one role, and that role already bypasses RLS — so it is safe to apply at any
-- time, in any order, against a database running any version of the code. It
-- breaks nothing, old or new. Its partner, 0031_graph_tables_revoke_client_
-- access.sql, takes privileges away and is the one with a deploy-ordering
-- constraint; see that file and docs/DEPLOYMENT.md §2.2.
--
-- WHY THIS IS NOT BELT-AND-BRACES
-- Plan 0014 moves every write to these tables onto the server's service-role
-- client. That makes `service_role`'s grant load-bearing where it previously
-- was not — and it cannot be taken for granted. Supabase no longer exposes
-- tables created by a migration to the Data API roles automatically
-- (supabase/config.toml's `auto_expose_new_tables`, unset, "matching the new
-- cloud default"), and 0006_grants.sql's `alter default privileges` names only
-- `authenticated`. Measured, not assumed: on a local `supabase start` with
-- 0001-0029 applied, `service_role` holds no DML on any pw_ table at all,
-- which is why tests/contract/conftest.py's setup recipe has to grant it by
-- hand. A production database very probably does have these grants — the
-- tombstone GC loop and the inbound webhook routes already write graph tables
-- on the service key and would be failing otherwise — but "very probably" is
-- not a basis for removing the other roles' access. Applying this first turns
-- that assumption into a fact before 0031 depends on it.
--
-- Idempotent, and a no-op in observable behaviour on any database that already
-- has these grants.

grant select, insert, update, delete on
  pw_requirements,
  pw_spec_documents,
  pw_tasks,
  pw_artifacts,
  pw_agent_runs,
  pw_stage_documents,
  pw_discussions
to service_role;

-- ----------------------------------------------------------------------------
-- 0031_graph_tables_revoke_client_access.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- 0031 — the seven graph tables become service-only: the server is the only
-- writer (docs/plans/0014-row-level-security-parity.md, Option A, decided
-- 2026-09-13; finding 2 of docs/cloud-codebase-review-2026-09-06.md).
--
-- >>> APPLY THIS ONE *AFTER* THE CODE DEPLOY, NOT BEFORE. <<<
-- It is the exception to the rule in docs/DEPLOYMENT.md §6 ("keep applying
-- migrations before deploying code that needs them"), and §2.2 documents the
-- exception. Every other migration in this directory adds or widens something,
-- so old code keeps working across the gap; this one takes privileges away
-- from the role the *old* code writes as. app/dependencies.py::get_repository
-- hands every auth_mode="supabase" request a repository scoped to the caller's
-- own JWT (SupabaseRepository.for_user), so before the paired code change,
-- production graph reads and writes execute as `authenticated`. Apply this
-- while that code is still live and every one of them fails with `permission
-- denied for table ...` until the rollout finishes.
--
-- The paired code change routes all seven tables onto the service-role client
-- (app/db/supabase_repository.py's _SERVICE_ONLY_TABLES / _table). Once it is
-- live, this migration is invisible to the application: the server never
-- reaches these tables as `authenticated` again. 0030 has already guaranteed
-- `service_role` holds the grants that client needs.
--
-- THE DEFECT
-- app/api/_guards.py enforces rules the database never did: admin-only
-- authoring of the `constitution`/`plan` stages (ADMIN_ONLY_STAGES), task
-- ownership on reassignment (app/api/sync.py::assign_task), admin-only
-- `verified` (app/api/sync.py::set_task_status), and — plan 0015's additions —
-- that a comment is an attributed statement nobody may post as somebody else
-- or overwrite (discussion_author_forbidden / discussion_forbidden). Every
-- policy governing these tables tests workspace membership and nothing else:
-- `pw_is_member` in 0003_auth_workspaces.sql's graph-table loop, in
-- 0011_discussions.sql, and in 0019_stage_documents.sql — while those same
-- migrations handed `authenticated` select/insert/update/delete outright. A
-- signed-in member who took their own Supabase JWT to the PostgREST data API
-- therefore wrote whatever the API would have refused, because the API was
-- never in that path. Measured, not assumed:
-- tests/rls/test_graph_table_grants.py drove exactly that with two real Auth
-- users against a real local stack, and every probe landed (200/201) before
-- this migration.
--
-- BASELINE THIS REPLACES (information_schema.role_table_grants, all seven
-- tables, on a database with 0001-0030 applied):
--   authenticated -> DELETE, INSERT, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE
--   anon          -> REFERENCES, TRIGGER, TRUNCATE
-- and pg_policies: one `*_rw` ALL policy per graph table whose USING and WITH
-- CHECK are both `pw_is_member(<the project's workspace>)`, plus
-- pw_stage_documents_read (SELECT) and pw_stage_documents_write (ALL), both
-- `pw_is_member(workspace_id)`. After this migration `authenticated` and
-- `anon` hold nothing on these seven.
--
-- WHY REVOKE RATHER THAN ADD POLICIES (Option B, rejected)
-- The rules are already duplicated once, between app/models/schemas.py's
-- FIELD_AUTHORITY/ADMIN_ONLY_STAGES and apps/web/src/lib/fieldAuthority.ts. A
-- third copy in SQL could not share sync.py's self-assign/self-unassign
-- branching without re-deriving it, and would drift silently the next time a
-- rule changed in Python only. Nothing loses a capability it uses: no client
-- reads or writes these tables over the data API — apps/web's only use of
-- @supabase/supabase-js is auth.getSession()/onAuthStateChange() in
-- src/lib/auth.tsx, and every graph read and write goes through apiFetch
-- against apps/cloud.
--
-- Precedent for the shape: 0020_repo_webhooks.sql ("there is nothing here a
-- member needs") and 0021_repo_webhooks_anon_revoke.sql, which closes the
-- same table's `anon` grant so the grant and the intent agree.
--
-- pw_discussions is in this set for the same reason as the other six, and was
-- missed on the first pass. It is in ENTITY_TYPES, it is written through the
-- same code path, and plan 0015's two discussion rules are API-only — so a
-- member could POST or PATCH pw_discussions directly and forge or overwrite
-- another member's comment, which is the same bypass class in a table the
-- plan's matrix did not enumerate. No new authorization rule is needed; the
-- guards already exist. Only the grant was missing.
--
-- THE POLICIES STAY, deliberately unmodified. Postgres checks the base GRANT
-- before RLS ever runs (the ordering 0006_grants.sql's own comment explains),
-- so with the grant gone the `pw_is_member`-only policies are unreachable
-- rather than misleading. Removing them would be a second, independent change
-- to review; leaving them costs nothing and keeps the diff honest.

revoke all on
  pw_requirements,
  pw_spec_documents,
  pw_tasks,
  pw_artifacts,
  pw_agent_runs,
  pw_stage_documents,
  pw_discussions
from authenticated;

revoke all on
  pw_requirements,
  pw_spec_documents,
  pw_tasks,
  pw_artifacts,
  pw_agent_runs,
  pw_stage_documents,
  pw_discussions
from anon;

-- Future graph tables do NOT inherit this posture: 0006_grants.sql's
-- `alter default privileges ... to authenticated` is still in force, so an
-- eighth graph table created later is born with the grant this migration
-- exists to remove — which is exactly how pw_discussions and
-- pw_stage_documents acquired theirs. Narrowing that default is a broader
-- change than plan 0014 scoped (it governs every table this app creates,
-- graph or not), so it is left alone and flagged here rather than silently
-- half-done. A new graph table needs adding to _SERVICE_ONLY_TABLES and to a
-- revoke of its own.

-- ----------------------------------------------------------------------------
-- 0032_tracker_account_identity.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- 0032 — a tracker reference is unique per *account*, not per provider
-- (docs/plans/0019-tracker-account-identity.md M1; finding 16 of
-- docs/cloud-codebase-review-2026-09-06.md).
--
-- THE DEFECT
-- `pw_task_links` was keyed `(provider, external_key)` (0005_tracker_links.sql
-- line 18), and `app/api/integrations.py::tracker_webhook` routed an inbound
-- delivery on exactly that pair. A Jira issue key is unique within a *site*,
-- not within Jira: project keys are short and operators reuse them, so two
-- workspaces that each connect their own Atlassian tenant and each run a
-- project keyed `PZ` both address the row `('jira', 'PZ-1')`. Whichever
-- mirrored first owned it; a delivery from either site then updated that one
-- task, and the comment path collided the same way on
-- `jira-comment-<jira's own comment id>`. The only thing standing between the
-- two was `JIRA_WEBHOOK_SECRET` — one process-wide value every configured site
-- holds, which proves "some configured Jira sent this" and never "which one".
--
-- THE SHAPE OF THE FIX IS NOT NEW
-- This is the same bug GitHub webhooks had (issue #3) and the same fix:
-- 0020_repo_webhooks.sql gave each repository its own row with its own
-- generated signing secret, and `app/api/github.py::github_webhook` routes on
-- an identity taken from the payload *before* it verifies, so an unrecognized
-- identity is dropped before its payload is trusted. `pw_workspace_integrations`
-- is that table for trackers: one row per (workspace, provider), carrying the
-- account it is bound to and that account's own secret.
--
-- WHY `account_key` IS THE SITE BASE URL
-- Jira Cloud webhooks carry no stable installation id this codebase can route
-- on — `JiraAdapter.handle_webhook` sees only `issue.key`, `fields` and
-- `comment` — but every payload's `issue.self` is an absolute URL on the
-- sending tenant's own host, and `JiraIntegrationConfig.base_url` (already
-- required and already host-allowlisted at configuration time) is unique per
-- tenant. Normalized to scheme + host, lowercased, trailing slash stripped
-- (`app/integrations/account.py::normalize_account_key`), that is an identity
-- both sides can produce. `unique (provider, account_key)` below is what turns
-- "unlikely to collide" into "cannot": two workspaces can only coexist here if
-- their sites genuinely differ, which is the one thing an operator cannot get
-- wrong the way they can get a three-letter project prefix wrong.

create table if not exists pw_workspace_integrations (
    workspace_id        uuid not null references pw_workspaces (id) on delete cascade,
    provider            text not null,                -- 'jira' | 'clickup'
    -- The normalized provider account this workspace is bound to (for Jira,
    -- the site base URL). NOT NULL and non-empty by constraint: `''` is the
    -- backfill value on pw_task_links.account_key below, and it must never be
    -- a value an inbound delivery can resolve to.
    account_key         text not null check (account_key <> ''),
    -- Ciphertext (app/secrets.py), exactly as pw_repo_webhooks.secret_ref.
    -- Generated per account at configuration time; never a shared value, and
    -- never plaintext in Postgres.
    webhook_secret_ref  text not null,
    created_at          timestamptz not null default now(),
    updated_at          timestamptz not null default now(),
    primary key (workspace_id, provider),
    constraint pw_workspace_integrations_account_unique unique (provider, account_key)
);

-- Link rows record which account they belong to. Additive with a default,
-- matching 0004_field_ownership.sql's style, so this migration applies to a
-- populated table without a rewrite of application state.
--
-- DELIBERATELY NOT BACKFILLED. A pre-existing link keeps `account_key = ''`,
-- which no configured account can ever equal (the check constraint above), so
-- an inbound delivery stops resolving it rather than resolving it to whichever
-- site asked first. That is the fail-closed direction: the cost is that a link
-- mirrored before this migration must be re-mirrored to start receiving
-- updates again, and the alternative — deriving each row's site from its
-- workspace's stored base_url — would have to guess for any workspace that has
-- since changed or removed its Jira config, and would make the primary key
-- below fail to build on exactly the colliding data this plan exists to
-- separate.
alter table pw_task_links add column if not exists account_key text not null default '';

-- The key the whole plan turns on. Every existing row carries account_key =
-- '', so the new three-column key is uniquely satisfiable by exactly the data
-- the two-column key already permitted; nothing can conflict at this point.
alter table pw_task_links drop constraint if exists pw_task_links_pkey;
alter table pw_task_links add constraint pw_task_links_pkey
  primary key (provider, account_key, external_key);

create index if not exists idx_pw_workspace_integrations_workspace
  on pw_workspace_integrations (workspace_id);

-- --------------------------------------------------------------------------
-- Grants and RLS
-- --------------------------------------------------------------------------
-- 0006_grants.sql's `alter default privileges ... to authenticated` is still
-- in force, so the table above was born with select/insert/update/delete for
-- `authenticated` (and Supabase's own bootstrap does the same for `anon`).
-- Take it all back first, then hand back only what a member legitimately
-- needs. Without this revoke, `webhook_secret_ref` would be readable by any
-- signed-in member's own JWT straight at the PostgREST data API — the exact
-- exposure 0021_repo_webhooks_anon_revoke.sql closed for the GitHub table.
revoke all on pw_workspace_integrations from authenticated;
revoke all on pw_workspace_integrations from anon;

-- Column-level SELECT, not table-level. Unlike pw_repo_webhooks ("there is
-- nothing here a member needs"), the non-secret columns here are a workspace's
-- own settings and are useful to a settings UI, so a member may read them —
-- but `webhook_secret_ref` is absent from this list and therefore unreachable
-- from a browser session, whatever the row policy says. `anon` gets nothing.
-- Writes are the server's alone: no insert/update/delete to any client role,
-- and app/db/supabase_repository.py puts this table in _SERVICE_ONLY_TABLES so
-- the server reaches it on the service-role client.
grant select (workspace_id, provider, account_key, created_at, updated_at)
  on pw_workspace_integrations to authenticated;

grant select, insert, update, delete on pw_workspace_integrations to service_role;

-- pw_task_links was never named in 0030_graph_tables_grant_service_role.sql,
-- and the inbound webhook route reads it as `service_role` (the route is
-- unauthenticated, so app/dependencies.py::get_repository hands it the
-- unscoped service repository). Additive, and a no-op where the grant already
-- exists — same reasoning as 0030's, applied to the one table this plan makes
-- the webhook path depend on.
grant select, insert, update, delete on pw_task_links to service_role;

-- ...and pw_task_links becomes service-only, exactly as the seven graph tables
-- did in 0031. This is not tidying: `account_key` is, as of this migration, a
-- tenant boundary the inbound webhook routes on, while the table's policy from
-- 0005_tracker_links.sql:30-32 tests workspace membership and nothing else and
-- 0006_grants.sql handed `authenticated` insert/update/delete outright. A
-- member could therefore POST a row into their own project naming a *victim's*
-- account_key. `_resolve_link`'s workspace check means the planted row is
-- dropped rather than acted on, so it is not a cross-tenant write — but the
-- planted row still occupies the victim's (provider, account_key, external_key)
-- triple and suppresses their legitimate mirror. Only the server writes here;
-- app/db/supabase_repository.py's _SERVICE_ONLY_TABLES is the paired change.
revoke all on pw_task_links from authenticated;
revoke all on pw_task_links from anon;

alter table pw_workspace_integrations enable row level security;

-- Mirrors pw_task_links' own policy in 0005_tracker_links.sql:27-32, narrowed
-- to SELECT: membership decides which rows a member sees, and the column grant
-- above decides which columns. There is no client-writable path, by design —
-- a member who could INSERT here could claim another tenant's account_key and
-- re-open the collision this migration closes.
drop policy if exists pw_workspace_integrations_read on pw_workspace_integrations;
create policy pw_workspace_integrations_read on pw_workspace_integrations for select
  using (pw_is_member(workspace_id));

-- ----------------------------------------------------------------------------
-- 0033_deployment_attribution.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- 0033 — a build's task set is written once, under a recorded state
-- (docs/plans/0024-delivery-evidence-graph.md M2).
--
-- Apply with scripts/migrate.py; never edit this file once applied — the
-- pw_schema_migrations ledger (0024) checksums it and reports drift.
--
-- THE DEFECT
-- 0027_deployment_tasks.sql opens by saying the task set is "frozen at
-- terminal state rather than derived on read, and that is the whole
-- decision", and app/deployments/attribution.py's docstring says the same
-- thing more sharply: "so a force-push, a reassignment or a later edit cannot
-- rewrite what somebody reviewed last Tuesday." Neither was true.
--
-- `freeze_build_tasks` carried no "already computed" check. Three call sites
-- reach it — app/api/github.py twice and the reconciliation sweep in
-- app/deployments/reconcile.py — and GitHub redelivers a webhook freely, so
-- every applicable redelivery re-queried the commit range, re-read the
-- current graph, and overwrote the stored set. A task edited or deleted
-- between the two deliveries silently changed the history of a build a
-- reviewer had already signed off. "Frozen" described an intent, not a
-- behaviour.
--
-- The write was not atomic either: the production adapter deleted the
-- existing set and inserted the new one as two separate PostgREST calls
-- (app/db/supabase_repository.py), so a failure between them erased the
-- record rather than leaving it stale. Of the two outcomes, the one that
-- loses evidence is the worse one.
--
-- THE SHAPE OF THE FIX
-- State on the row, and one function that owns the transition. The function
-- is the only thing that may write pw_deployment_tasks, so the delete, the
-- insert and the stamp cannot come apart, and the "already frozen" test
-- happens under a row lock rather than in the application between two round
-- trips. `attribution_state` is cleared in exactly one place — the admin-only
-- POST /projects/{id}/deployments/{id}/reattribute — so a correction is a
-- deliberate, attributable act rather than a consequence of GitHub's retry
-- policy.
--
-- The function precedent is pw_rag_match_chunks (0023_configurable_embed_dim
-- .sql); the client-side precedent is the `.rpc(...)` call in
-- app/db/supabase_repository.py::vector_search.

-- 'uncomputed' is the honest default for every row that already exists: those
-- builds were attributed under the old unfrozen behaviour, so the platform
-- genuinely does not know whether what is stored is what shipped. The web app
-- renders that as "not yet recorded" rather than as an empty build, which is
-- the point of plan 0024's third defect — an empty result and an uncomputed
-- result are different facts and used to look identical.
alter table pw_deployments
  add column if not exists attribution_state text not null default 'uncomputed';

alter table pw_deployments
  add column if not exists attributed_at timestamptz;

-- Two values, and a constraint rather than a comment, because every reader
-- (the API serialiser, the web rollup, the reattribute endpoint) branches on
-- this string and a third value would reach them as a silent fall-through.
alter table pw_deployments
  drop constraint if exists pw_deployments_attribution_state_check;
alter table pw_deployments
  add constraint pw_deployments_attribution_state_check
  check (attribution_state in ('uncomputed', 'frozen'));

-- Freeze this build's task set, once.
--
-- Returns true when it wrote, false when the row was already frozen or does
-- not exist. A false return is the normal, expected answer to a redelivery —
-- not an error — and the caller reads the stored set back rather than
-- treating its own freshly computed list as authoritative.
--
-- `for update` is what makes the check-then-write safe: two concurrent
-- deliveries of the same terminal event serialise here instead of both
-- observing 'uncomputed' and both writing.
--
-- security invoker (the default) on purpose. The only caller is the server's
-- service-role client, which already holds DML on both tables — every write
-- on this path goes through it today. A definer function would hand the
-- table owner's rights to whoever holds execute, which is a larger grant
-- than this needs.
create or replace function pw_freeze_deployment_tasks(
    p_deployment_id uuid,
    p_task_ids uuid[]
) returns boolean
language plpgsql volatile set search_path = public as $$
declare
  v_state text;
begin
  select attribution_state into v_state
    from pw_deployments
   where id = p_deployment_id
     for update;

  if not found then
    return false;
  end if;

  if v_state = 'frozen' then
    return false;
  end if;

  delete from pw_deployment_tasks where deployment_id = p_deployment_id;

  -- `with ordinality` carries the caller's order into `position`, which is
  -- what 0027 added it for: the Preview tab's list must read the same way
  -- twice. An empty array inserts nothing and still freezes the row — that
  -- is a build that genuinely closed no tasks, and it is now distinguishable
  -- from one nobody ever attributed.
  insert into pw_deployment_tasks (deployment_id, task_id, position)
  select p_deployment_id, t.tid, (t.ord - 1)::integer
    from unnest(p_task_ids) with ordinality as t(tid, ord)
  on conflict (deployment_id, task_id) do nothing;

  update pw_deployments
     set attribution_state = 'frozen',
         attributed_at = now()
   where id = p_deployment_id;

  return true;
end;
$$;

-- Default execute on a function is granted to PUBLIC, which would let any
-- authenticated member freeze or (via the endpoint's absence, merely attempt
-- to) rewrite an attribution. Members read their project's attribution and
-- never author one — the same posture 0027 set on the table itself.
revoke execute on function pw_freeze_deployment_tasks(uuid, uuid[]) from public;
revoke execute on function pw_freeze_deployment_tasks(uuid, uuid[]) from anon;
revoke execute on function pw_freeze_deployment_tasks(uuid, uuid[]) from authenticated;
grant execute on function pw_freeze_deployment_tasks(uuid, uuid[]) to service_role;

-- The function writes both tables on the caller's own rights, so name that
-- role's grant here rather than assuming it (the same reasoning as 0030: on a
-- clean local `supabase start`, service_role holds no DML on any pw_ table,
-- which is why tests/contract/conftest.py has to grant it by hand). Adding a
-- privilege to a role that already bypasses RLS is safe in any order.
grant select, insert, update, delete on pw_deployments to service_role;
grant select, insert, update, delete on pw_deployment_tasks to service_role;

-- ----------------------------------------------------------------------------
-- 0034_repo_analyses.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- 0034 — what the platform read out of an imported repository
-- (docs/plans/0027-brownfield-repo-import.md M1).
--
-- Apply with scripts/migrate.py; never edit this file once applied — the
-- pw_schema_migrations ledger (0024) checksums it and reports drift.
--
-- One row per project, the *current* analysis: a re-analysis replaces it, and
-- nothing reads an older one. `snapshot` is the deterministic read
-- (app/imports/snapshot.py) — tree summary, detected stack, excerpts of a
-- fixed list of files — and `baseline` is the one model-written document over
-- it, which the Planner's plan and tasks stages are gated on for an imported
-- project (app/api/generation.py). The baseline is stored rather than
-- recomputed because it cost the workspace's daily token budget (ADR 0027).
--
-- Not a stage document: pw_stage_documents.stage is a closed CHECK on
-- purpose, and the baseline is an input to planning, not a Spec Kit stage.
--
-- Secret-shaped files are filtered out before the snapshot is built, so no
-- credential reaches `snapshot`. The content that does reach it is still a
-- customer's source excerpts, which is why the table is service-only below.

create table if not exists pw_repo_analyses (
    project_id uuid primary key references pw_projects (id) on delete cascade,
    workspace_id uuid not null references pw_workspaces (id) on delete cascade,
    commit_sha text not null,
    snapshot jsonb not null default '{}'::jsonb,
    baseline text not null default '',
    status text not null default 'snapshot_ready',
    created_by uuid,
    updated_at timestamptz not null default now()
);

alter table pw_repo_analyses
  drop constraint if exists pw_repo_analyses_status_check;
alter table pw_repo_analyses
  add constraint pw_repo_analyses_status_check
  check (status in ('snapshot_ready', 'baseline_ready', 'failed'));

alter table pw_repo_analyses enable row level security;

-- Service-only from birth, the posture 0031 gave the seven graph tables after
-- the fact. 0006_grants.sql's `alter default privileges ... to authenticated`
-- is still in force, so this table is born with a member grant that the
-- revokes below take straight back: the only enforcement of "admin-only
-- analysis, admin-only baseline edit" is app/api/repo_analysis.py, and a
-- member holding a direct grant here would walk around it. No client reads
-- this table over the data API; apps/web reads it through apps/cloud.
revoke all on pw_repo_analyses from authenticated;
revoke all on pw_repo_analyses from anon;
grant select, insert, update, delete on pw_repo_analyses to service_role;

-- ----------------------------------------------------------------------------
-- 0035_project_repo_origin.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- 0035 — how a project came by its repository (docs/plans/0027-brownfield-repo-import.md).
--
-- Apply with scripts/migrate.py; never edit this file once applied — the
-- pw_schema_migrations ledger (0024) checksums it and reports drift.
--
-- `repo_origin` is 'imported' when POST /projects adopted a repository the
-- user picked, 'created' when create_repository created one. It replaces the
-- repository's GitHub description as the signal create_repository's
-- crash-window retry reads to decide between the full seed (a repository the
-- platform created, safe to write at its conventional paths) and the
-- relocated, non-overwriting one: a description is editable by anyone with
-- admin on the repository, so it could be set to the platform's own string
-- to earn an imported repository the overwriting seed.
--
-- Deliberately NOT backfilled. A project with a repo_url and no origin is
-- either an import or a from-scratch project caught in the crash window
-- between recording repo_url and flipping to repo_created, and nothing in
-- this table tells the two apart. The application treats NULL as imported
-- (app/models/schemas.py::Project.is_imported): the relocated seed and the
-- baseline gate are the readings that cannot overwrite a team's files. A
-- backfill guessing 'imported' from `repo_url is not null` would bake the
-- same guess into data and lose the NULL that marks it as one.

alter table pw_projects add column if not exists repo_origin text;

alter table pw_projects
  drop constraint if exists pw_projects_repo_origin_check;
alter table pw_projects
  add constraint pw_projects_repo_origin_check
  check (repo_origin is null or repo_origin in ('imported', 'created'));

-- ----------------------------------------------------------------------------
-- 0036_projects_server_write_only.sql (at pre-promptworkspace-rename)
-- ----------------------------------------------------------------------------

-- 0036 — pw_projects becomes server-written: members keep their scoped read,
-- and lose their direct write (docs/plans/0027-brownfield-repo-import.md,
-- security review follow-up N1).
--
-- Apply with scripts/migrate.py; never edit this file once applied — the
-- pw_schema_migrations ledger (0024) checksums it and reports drift.
--
-- >>> APPLY THIS ONE *AFTER* THE CODE DEPLOY, NOT BEFORE. <<<
-- Same reason as 0031 (docs/DEPLOYMENT.md §2.2): it takes privileges away
-- from the role the previous code wrote this table as. Before the paired code
-- change, SupabaseRepository wrote pw_projects through the caller's own JWT
-- (for_user), i.e. as `authenticated`; applied ahead of the rollout, every
-- project create, repository creation, lifecycle transition, policy-scope and
-- deployment-config save and graph push fails with `permission denied for
-- table pw_projects` until the new code is live. The paired change routes
-- those writes onto the service-role client (`_SERVICE_WRITE_TABLES` /
-- `_write_table` in app/db/supabase_repository.py); once it is live this
-- migration is invisible to the application.
--
-- THE DEFECT
-- 0006_grants.sql granted `authenticated` select/insert/update/delete on
-- pw_projects, and its only policy, pw_projects_rw (0003_auth_workspaces.sql),
-- tests `pw_is_member(workspace_id)` and nothing else. So any workspace member
-- could PATCH their own project row straight through PostgREST and set the
-- columns that only the server is meant to write: `repo_origin` (plan 0027's
-- provenance — `created` earns an imported repository the overwriting seed),
-- `repo_url`/`repo_id`/`repo_default_branch` (which repository the platform
-- writes secrets, a webhook and a seed commit into), `lifecycle_status` (the
-- tech-review gate), and the admin-only `policy_scope` and
-- `deployment_config`/`deployment_state`. Every one of those has an app-layer
-- rule in app/api; none of them had one in the database.
--
-- WHY REVOKE THE TABLE-LEVEL WRITE, NOT A FEW COLUMNS
-- A column-level REVOKE does nothing while the table-level UPDATE grant
-- stands, so the only way to protect columns is to revoke table-level UPDATE
-- and grant back per-column UPDATE on what a client legitimately writes. No
-- client writes this table at all: apps/web uses @supabase/supabase-js for
-- auth sessions only, and no surface in apps/* or packages/* calls PostgREST
-- on pw_projects — every project write goes through apps/cloud. Even the one
-- column a member could arguably own, `name`, has no rename route in the API,
-- so there is no column to grant back. INSERT, UPDATE and DELETE go outright:
-- the plan 0014 posture (0031), applied to writes only.
--
-- WHY SELECT STAYS
-- Unlike the graph tables, reads of pw_projects still run on the caller's JWT
-- and RLS is what scopes them to the caller's workspaces (`list_projects`,
-- `get_project`), so the member read grant is real defence in depth and is
-- kept, as is the pw_projects_rw policy that now governs only it. A project
-- deleted through its workspace's cascade is unaffected: referential actions
-- run with the referencing table owner's rights, not the caller's.

-- TRUNCATE, REFERENCES and TRIGGER go with the writes: PostgREST exposes none
-- of them, but TRUNCATE ignores RLS entirely, and nothing a client does needs
-- any of the three. `authenticated` is left holding SELECT alone; `anon`,
-- which no policy admits anyway, nothing.
revoke insert, update, delete, truncate, references, trigger on pw_projects from authenticated;
revoke all on pw_projects from anon;

-- The client the paired code change writes with. Idempotent where the
-- platform's default privileges already granted it (hosted), required where
-- they did not (a local stack, see tests/rls/conftest.py).
grant select, insert, update, delete on pw_projects to service_role;
